183	+import nodemailer from 'nodemailer';
184	+import { cityName, formatDate, formatOtherTime, formatSpan, formatWhen } from '../shared/time.ts';
185	+
186	+export type EmailMessage = { to: string; subject: string; text: string };
187	+export type Mailer = { send(message: EmailMessage): Promise<void> };
188	+export type EmailBooking = { id: string; startsAt: Date; parentName: string; parentEmail: string; childName: string; parentTimeZone: string;
189	+  classLink: string; mentor: { name: string; email: string; timeZone: string } };
190	+
191	+const CLASS_MINUTES = 60;
192	+const first = (name: string) => name.trim().split(/\s+/)[0] ?? name;
193	+
194	+/** One email per side; each leads with its reader's own time and adds the other side's time (with its date when the days differ). */
195	+export function renderEmails(b: EmailBooking, appUrl: string): { parent: EmailMessage; mentor: EmailMessage } {
196	+  const start = b.startsAt;
197	+  const end = new Date(start.getTime() + CLASS_MINUTES * 60_000);
198	+  const { mentor } = b;
199	+  const when = (tz: string) => `${formatDate(start, tz)}, ${formatSpan(start, end, tz)}`;
200	+
201	+  const parent = [
202	+    `Hi ${first(b.parentName)},`,
203	+    '',
204	+    `${b.childName}'s free trial class is booked.`,
205	+    '',
206	+    `When: ${when(b.parentTimeZone)}`,
207	+    `Mentor: ${mentor.name}, joining from ${cityName(mentor.timeZone)}, where it's ${formatOtherTime(start, mentor.timeZone, b.parentTimeZone)}`,
208	+    `Class link: ${b.classLink}`,
209	+    '',
210	+    `See your booking: ${appUrl}/bookings/${b.id}`,
211	+  ];
212	+  const mentorText = [
213	+    `Hi ${first(mentor.name)},`,
214	+    '',
215	+    'You have a new trial class.',
216	+    '',
217	+    `When: ${when(mentor.timeZone)}`,
218	+    `For the family: ${formatOtherTime(start, b.parentTimeZone, mentor.timeZone)} in ${cityName(b.parentTimeZone)}`,
219	+    `Child: ${b.childName}`,
220	+    `Parent: ${b.parentName}`,
221	+    `Class link: ${b.classLink}`,
222	+  ];
223	+
224	+  return {
225	+    parent: { to: b.parentEmail, subject: `${b.childName}'s free trial class: ${formatWhen(start, b.parentTimeZone)}`, text: parent.join('\n') },
226	+    mentor: { to: mentor.email, subject: `New trial class: ${formatWhen(start, mentor.timeZone)}`, text: mentorText.join('\n') },
227	+  };
228	+}
229	+
230	+/** Sends through the given SMTP url. A refused connection rejects; there are no retries. */
231	+export function createSmtpMailer(smtpUrl: string): Mailer {
232	+  const transport = nodemailer.createTransport(smtpUrl);
233	+  return {
234	+    async send({ to, subject, text }) {
235	+      await transport.sendMail({ from: 'Codeyoung Trials <trials@codeyoung.example>', to, subject, text });
236	+    },
237	+  };
238	+}
